//! Icon library: typed access to every icon of the application (same scheme as RustView).
//!
//! `assets/icons/icons.toml` is the single source of truth; `build.rs` generates the Rust enum [`Icon`] (this module) and
//! the Slint enum `IconId` (see `ui/icons.slint`) from it, so both sides always agree. All icons are Tabler SVGs
//! (`assets/icons/tabler/`), tinted with a theme color by `AppIcon` in Slint.

// `Icon`, `TABLER_VERSION` and `SPECS`, generated by `build/icon_registry.rs` from the manifest.
include!(concat!(env!("OUT_DIR"), "/icon_registry.rs"));

/// Static description of one icon (generated from the manifest).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct IconSpec {
    /// Manifest id in `snake_case`, e.g. `panel_queue`.
    pub id: &'static str,
    /// SVG path relative to `assets/`, e.g. `icons/tabler/outline/list-details.svg`.
    pub source: &'static str,
    /// `false` for icons that keep their own colors.
    pub monochrome: bool,
    pub doc: &'static str,
    /// Additional names accepted by [`Icon::from_name`].
    pub aliases: &'static [&'static str],
    /// Embedded SVG source text.
    pub svg: &'static str,
}

impl Icon {
    /// The static description of the icon.
    pub fn spec(self) -> Option<&'static IconSpec> {
        let index = Icon::ALL.iter().position(|icon| *icon == self)?;
        SPECS.get(index)
    }

    /// Manifest id, e.g. `"panel_queue"`.
    pub fn id(self) -> &'static str {
        self.spec().map_or("", |spec| spec.id)
    }
}

impl std::fmt::Display for Icon {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.id())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_icon_has_a_spec_and_round_trips_by_name() {
        for icon in Icon::ALL {
            let spec = icon.spec().unwrap();
            assert!(spec.svg.contains("<svg"), "{icon}");
            assert_eq!(Icon::from_name(spec.id), Some(icon));
            for alias in spec.aliases {
                assert_eq!(Icon::from_name(alias), Some(icon));
            }
        }
    }

    #[test]
    fn names_are_case_and_dash_insensitive() {
        assert_eq!(Icon::from_name("Panel-Queue"), Some(Icon::PanelQueue));
        assert_eq!(Icon::from_name("no such icon"), None);
    }
}
